import type { Vec3 } from '../contracts/math';
import type { Hole, ObstacleDescriptor } from '../courses/types';
import type { MinimapBounds, MinimapPoint } from '../dev/PresentationMinimap';

export interface MinimapModel {
  bounds: MinimapBounds;
  points: MinimapPoint[];
}

const PADDING_RATIO = 0.05;
const FALLBACK_SPAN = 1;
const CANVAS_WIDTH = 200;
const CANVAS_HEIGHT = 140;

const SPAWN_COLOR = '#8fd6ff';
const CUP_COLOR = '#ffd166';
const BALL_COLOR = '#ffffff';
const HAZARD_COLOR = '#ff6b6b';
const MOVING_COLOR = '#c084fc';
const SOLID_COLOR = '#64748b';

type ObstacleType = ObstacleDescriptor['type'];

const HAZARD_TYPES: readonly ObstacleType[] = ['water', 'void', 'reset-zone'];
const MOVING_TYPES: readonly ObstacleType[] = ['spinner', 'windmill', 'gate', 'platform'];

function obstacleColor(type: ObstacleType): string {
  if (HAZARD_TYPES.includes(type)) return HAZARD_COLOR;
  if (MOVING_TYPES.includes(type)) return MOVING_COLOR;
  return SOLID_COLOR;
}

function padAxis(a: number, b: number): { min: number; max: number } {
  const min = Math.min(a, b);
  const max = Math.max(a, b);
  const span = max - min;
  const padding = span > 0 ? span * PADDING_RATIO : FALLBACK_SPAN / 2;
  return { min: min - padding, max: max + padding };
}

/** Projects a hole (and the optional live ball position) onto a top-down minimap model. */
export function buildMinimapModel(hole: Hole, ballPosition?: Vec3): MinimapModel {
  const x = padAxis(hole.bounds.min.x, hole.bounds.max.x);
  const z = padAxis(hole.bounds.min.z, hole.bounds.max.z);
  const points: MinimapPoint[] = [
    { x: hole.spawn.x, z: hole.spawn.z, color: SPAWN_COLOR, label: 'START' },
    { x: hole.cup.position.x, z: hole.cup.position.z, color: CUP_COLOR, label: 'HOLE' },
  ];
  for (const obstacle of hole.obstacles) {
    points.push({
      x: obstacle.transform.position.x,
      z: obstacle.transform.position.z,
      color: obstacleColor(obstacle.type),
      radius: 3,
    });
  }
  if (ballPosition) {
    points.push({ x: ballPosition.x, z: ballPosition.z, color: BALL_COLOR, radius: 5 });
  }
  return { bounds: { minX: x.min, maxX: x.max, minZ: z.min, maxZ: z.max }, points };
}

/** Small in-game minimap widget; hidden until enabled from settings. */
export class Minimap {
  readonly element: HTMLElement;
  private readonly canvas: HTMLCanvasElement;

  constructor() {
    this.element = document.createElement('div');
    this.element.className = 'cpa-minimap';
    this.element.hidden = true;
    this.canvas = document.createElement('canvas');
    this.canvas.width = CANVAS_WIDTH;
    this.canvas.height = CANVAS_HEIGHT;
    this.element.append(this.canvas);
  }

  render(model: MinimapModel): void {
    const ctx = this.context();
    if (!ctx) return;
    const { bounds, points } = model;
    const spanX = Math.max(bounds.maxX - bounds.minX, 0.001);
    const spanZ = Math.max(bounds.maxZ - bounds.minZ, 0.001);
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.fillStyle = 'rgba(6, 12, 20, 0.78)';
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.2)';
    ctx.strokeRect(0.5, 0.5, CANVAS_WIDTH - 1, CANVAS_HEIGHT - 1);
    for (const point of points) {
      const px = ((point.x - bounds.minX) / spanX) * CANVAS_WIDTH;
      const py = CANVAS_HEIGHT - ((point.z - bounds.minZ) / spanZ) * CANVAS_HEIGHT;
      ctx.beginPath();
      ctx.fillStyle = point.color ?? SOLID_COLOR;
      ctx.arc(px, py, point.radius ?? 4, 0, Math.PI * 2);
      ctx.fill();
      if (point.label) {
        ctx.fillStyle = '#ffffff';
        ctx.font = '10px system-ui, sans-serif';
        ctx.fillText(point.label, px + 6, py - 5);
      }
    }
  }

  setVisible(visible: boolean): void {
    this.element.hidden = !visible;
  }

  get visible(): boolean {
    return !this.element.hidden;
  }

  private context(): CanvasRenderingContext2D | null {
    try {
      return this.canvas.getContext('2d');
    } catch {
      return null;
    }
  }
}
