// @vitest-environment jsdom
import { describe, expect, it } from 'vitest';
import type { Vec3 } from '../contracts/math';
import type { Hole, ObstacleDescriptor } from '../courses/types';
import { Minimap, buildMinimapModel } from './Minimap';

function v(x: number, y: number, z: number): Vec3 {
  return { x, y, z };
}

const OBSTACLES: ObstacleDescriptor[] = [
  { id: 'wall-1', type: 'wall', transform: { position: v(2, 0, 1) }, size: v(4, 1, 0.5) },
  { id: 'water-1', type: 'water', transform: { position: v(-3, 0, 2) }, size: v(3, 0.2, 3) },
  {
    id: 'spin-1',
    type: 'spinner',
    transform: { position: v(0, 0, -2) },
    size: v(2, 1, 0.4),
    motion: { kind: 'rotate', axis: v(0, 1, 0), speed: 1.5 },
  },
];

function hole(overrides: Partial<Hole> = {}): Hole {
  return {
    id: 'h1',
    name: 'Test Hole',
    par: 3,
    spawn: v(-8, 0, -4),
    cup: { position: v(8, 0, 4), radius: 0.12, captureDepth: 0.2 },
    bounds: { min: v(-10, 0, -5), max: v(10, 4, 5) },
    surfaces: [],
    obstacles: OBSTACLES,
    ...overrides,
  };
}

describe('buildMinimapModel', () => {
  it('always emits the start and hole markers first', () => {
    const model = buildMinimapModel(hole());
    expect(model.points[0]).toMatchObject({ x: -8, z: -4, color: '#8fd6ff', label: 'START' });
    expect(model.points[1]).toMatchObject({ x: 8, z: 4, color: '#ffd166', label: 'HOLE' });
  });

  it('colours obstacles by hazard, moving and solid kinds', () => {
    const model = buildMinimapModel(hole());
    const [, , wall, water, spinner] = model.points;
    expect(wall?.color).toBe('#64748b');
    expect(water?.color).toBe('#ff6b6b');
    expect(spinner?.color).toBe('#c084fc');
    expect(model.points).toHaveLength(5);
  });

  it('appends the ball point last and omits it without a position', () => {
    const withBall = buildMinimapModel(hole(), v(1.5, 0.2, -2.5));
    expect(withBall.points).toHaveLength(6);
    expect(withBall.points.at(-1)).toEqual({ x: 1.5, z: -2.5, color: '#ffffff', radius: 5 });
    const withoutBall = buildMinimapModel(hole());
    expect(withoutBall.points.some((p) => p.color === '#ffffff')).toBe(false);
  });

  it('pads bounds by 5 percent and keeps degenerate bounds non zero', () => {
    const padded = buildMinimapModel(hole()).bounds;
    expect(padded).toEqual({ minX: -11, maxX: 11, minZ: -5.5, maxZ: 5.5 });
    const flat = buildMinimapModel(hole({ bounds: { min: v(4, 0, 4), max: v(4, 0, 4) } })).bounds;
    expect(flat.maxX - flat.minX).toBeGreaterThan(0);
    expect(flat.maxZ - flat.minZ).toBeGreaterThan(0);
  });
});

describe('Minimap widget', () => {
  it('builds a 200x140 canvas and renders without throwing', () => {
    const minimap = new Minimap();
    const canvas = minimap.element.querySelector('canvas');
    expect(minimap.element.className).toBe('cpa-minimap');
    expect(canvas?.width).toBe(200);
    expect(canvas?.height).toBe(140);
    expect(() => minimap.render(buildMinimapModel(hole(), v(0, 0, 0)))).not.toThrow();
  });

  it('toggles visibility', () => {
    const minimap = new Minimap();
    expect(minimap.visible).toBe(false);
    minimap.setVisible(true);
    expect(minimap.visible).toBe(true);
    minimap.setVisible(false);
    expect(minimap.visible).toBe(false);
  });
});
